// --- STATE ---
        let currentMode = 'embed'; // 'embed' or 'extract'
        let sourceImage = null;
        let originalFilename = 'image';
        // --- DOM ELEMENTS ---
        const dropZone = document.getElementById('drop-zone');
        const fileInput = document.getElementById('file-input');
        const uploadPrompt = document.getElementById('upload-prompt');
        const imagePreviewContainer = document.getElementById('image-preview-container');
        const imagePreview = document.getElementById('image-preview');
        const imgDimensions = document.getElementById('img-dimensions');
        const actionBtn = document.getElementById('action-btn');
        const extractBtn = document.getElementById('extract-btn');
        const payloadInput = document.getElementById('payload-input');
        const capacityIndicator = document.getElementById('capacity-indicator');
        const canvas = document.getElementById('processing-canvas');
        const ctx = canvas.getContext('2d');
        const extractResult = document.getElementById('extraction-result');
        const extractStatus = document.getElementById('extract-status');
        // --- UI LOGIC ---
        function setMode(mode) {
            currentMode = mode;
            document.getElementById('btn-embed').classList.toggle('active', mode === 'embed');
            document.getElementById('btn-extract').classList.toggle('active', mode === 'extract');
            if (mode === 'embed') {
                document.getElementById('embed-ui').classList.remove('hidden');
                document.getElementById('extract-ui').classList.add('hidden');
            } else {
                document.getElementById('embed-ui').classList.add('hidden');
                document.getElementById('extract-ui').classList.remove('hidden');
                extractResult.innerHTML = "Upload an image to scan for LSB payloads.";
                extractResult.classList.replace('text-emerald-400', 'text-slate-500');
                extractStatus.innerText = "Awaiting Signal...";
            }
            checkReadyState();
        }
        function checkReadyState() {
            if (sourceImage) {
                if (currentMode === 'embed') {
                    actionBtn.disabled = payloadInput.value.length === 0;
                } else {
                    extractBtn.disabled = false;
                }
            } else {
                actionBtn.disabled = true;
                extractBtn.disabled = true;
            }
        }
        function checkCapacity() {
            checkReadyState();
            if (sourceImage) {
                const totalPixels = sourceImage.width * sourceImage.height;
                const maxChars = Math.floor((totalPixels * 3) / 8) - 4; // -4 for terminating sequence
                const currentLength = payloadInput.value.length;
                if (currentLength > maxChars) {
                    capacityIndicator.innerText = `Capacity Exceeded (${currentLength.toLocaleString()} / ${maxChars.toLocaleString()})`;
                    capacityIndicator.classList.remove('text-slate-500');
                    capacityIndicator.classList.add('text-red-500');
                    actionBtn.disabled = true; // Force disable if capacity exceeded
                } else {
                    capacityIndicator.innerText = `Capacity: ${maxChars.toLocaleString()} chars`;
                    capacityIndicator.classList.remove('text-red-500');
                    capacityIndicator.classList.add('text-slate-500');
                }
            }
        }
        // --- FILE HANDLING LOGIC ---
        dropZone.addEventListener('dragover', (e) => {
            e.preventDefault();
            dropZone.classList.add('dragover');
        });
        dropZone.addEventListener('dragleave', () => {
            dropZone.classList.remove('dragover');
        });
        dropZone.addEventListener('drop', (e) => {
            e.preventDefault();
            dropZone.classList.remove('dragover');
            if (e.dataTransfer.files.length) {
                handleFile(e.dataTransfer.files[0]);
            }
        });
        fileInput.addEventListener('change', (e) => {
            if (e.target.files.length) {
                handleFile(e.target.files[0]);
            }
        });
        function handleFile(file) {
            if (!file.type.match('image.*')) {
                alert('Please upload a valid image file (PNG/JPG).');
                return;
            }
            originalFilename = file.name.split('.')[0];
            const reader = new FileReader();
            reader.onload = (e) => {
                const img = new Image();
                img.onload = () => {
                    sourceImage = img;
                    // UI Updates
                    imagePreview.src = e.target.result;
                    uploadPrompt.classList.add('hidden');
                    imagePreviewContainer.classList.remove('hidden');
                    imgDimensions.innerText = `${img.width} x ${img.height}`;
                    checkCapacity(); // Initialize capacity indicator state
                };
                img.src = e.target.result;
            };
            reader.readAsDataURL(file);
        }
        // --- STEGANOGRAPHY CORE ---
        // Helper: Convert string to binary string
        function textToBinary(text) {
            let bin = '';
            for (let i = 0; i < text.length; i++) {
                let charBin = text.charCodeAt(i).toString(2).padStart(8, '0');
                bin += charBin;
            }
            // Add termination character (NULL byte: 00000000)
            bin += '00000000';
            return bin;
        }
        // Helper: Convert binary string back to text
        function binaryToText(binString) {
            let text = '';
            for (let i = 0; i < binString.length; i += 8) {
                let byte = binString.substr(i, 8);
                if (byte === '00000000') break; // Reached termination
                text += String.fromCharCode(parseInt(byte, 2));
            }
            return text;
        }
        // EMBED
        function executeEmbed() {
            if (!sourceImage) return;
            const text = payloadInput.value;
            if (!text) return;
            // Setup Canvas
            canvas.width = sourceImage.width;
            canvas.height = sourceImage.height;
            ctx.drawImage(sourceImage, 0, 0);
            const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const data = imageData.data;
            const binaryMsg = textToBinary(text);
            if (binaryMsg.length > (data.length / 4) * 3) {
                alert("Payload too large for this image resolution.");
                return;
            }
            let bitIndex = 0;
            const msgLength = binaryMsg.length;
            // Loop through pixels. data array format: R, G, B, A
            for (let i = 0; i < data.length && bitIndex < msgLength; i++) {
                // Skip Alpha channel (every 4th element) to preserve transparency
                if ((i + 1) % 4 === 0) continue;
                let bit = parseInt(binaryMsg[bitIndex]);
                // Clear the LSB and set it to our bit
                data[i] = (data[i] & ~1) | bit;
                bitIndex++;
            }
            // Write back to canvas
            ctx.putImageData(imageData, 0, 0);
            // Trigger Download
            const link = document.createElement('a');
            link.download = `${originalFilename}_watermarked.png`; // Force PNG
            link.href = canvas.toDataURL('image/png');
            link.click();
            alert("Embedding complete! PNG saved to your device. Remember to never compress this file.");
        }
        // EXTRACT
        function executeExtract() {
            if (!sourceImage) return;
            extractStatus.innerText = "Analyzing Matrix...";
            // Setup Canvas
            canvas.width = sourceImage.width;
            canvas.height = sourceImage.height;
            ctx.drawImage(sourceImage, 0, 0);
            const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const data = imageData.data;
            let extractedBinary = '';
            let charBinary = '';
            // Read LSBs
            for (let i = 0; i < data.length; i++) {
                if ((i + 1) % 4 === 0) continue; // Skip Alpha
                let bit = data[i] & 1;
                charBinary += bit;
                // Every 8 bits, check if we hit the terminator
                if (charBinary.length === 8) {
                    if (charBinary === '00000000') {
                        break; // End of payload
                    }
                    extractedBinary += charBinary;
                    charBinary = '';
                }
                // Safety cutoff for completely random noise/unwatermarked images (e.g. max 10k chars)
                if (extractedBinary.length > 80000) break;
            }
            const extractedText = binaryToText(extractedBinary);
            if (extractedText.trim().length > 0 && /^[ -~\t\n\r]+$/.test(extractedText)) {
                // Heuristic: If it looks like printable ASCII
                extractResult.innerHTML = `<div><strong class="text-xs text-slate-400 block mb-2 uppercase tracking-widest">Payload Discovered:</strong><span class="text-emerald-400 font-bold break-all">${extractedText}</span></div>`;
                extractStatus.innerText = "Signal Locked";
            } else {
                extractResult.innerHTML = "No valid steganographic payload detected or file was compressed.";
                extractResult.classList.replace('text-emerald-400', 'text-red-400');
                extractStatus.innerText = "Signal Null";
            }
        }
        // --- SCROLL LOGIC ---
